class Solution {
public:
    int generateKey(int num1, int num2, int num3) {
        auto pad = [](int val) {
            string s = to_string(val);
            while (s.size() < 4) s = "0" + s;
            return s;
        };
        string s1 = pad(num1), s2 = pad(num2), s3 = pad(num3);
        string key = "";
        for (int i = 0; i < 4; ++i) {
            int d = min({s1[i] - '0', s2[i] - '0', s3[i] - '0'});
            key += to_string(d);
        }
        return stoi(key);
    }
};

class Solution {
    public int generateKey(int num1, int num2, int num3) {
        String s1 = String.format("%04d", num1);
        String s2 = String.format("%04d", num2);
        String s3 = String.format("%04d", num3);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 4; ++i) {
            int d = Math.min(s1.charAt(i) - '0', Math.min(s2.charAt(i) - '0', s3.charAt(i) - '0'));
            sb.append(d);
        }
        return Integer.parseInt(sb.toString());
    }
}

var generateKey = function(num1, num2, num3) {
    const s1 = String(num1).padStart(4, '0');
    const s2 = String(num2).padStart(4, '0');
    const s3 = String(num3).padStart(4, '0');
    let res = "";
    for (let i = 0; i < 4; i++) {
        res += Math.min(Number(s1[i]), Number(s2[i]), Number(s3[i]));
    }
    return parseInt(res, 10);
};
